using AISmartLearning.API.Data;using AISmartLearning.API.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AISmartLearning.API.Controllers;
[ApiController][Authorize][Route("api/dashboard")] public sealed class DashboardController(AppDbContext db):ControllerBase {
[HttpGet("summary")] public async Task<IActionResult> Summary(CancellationToken ct){var role=User.FindFirst(System.Security.Claims.ClaimTypes.Role)?.Value??"Student";var uid=InteractionLogService.UserId(User);if(role=="Admin")return Ok(new{role,totalUsers=await db.Users.CountAsync(ct),totalStudents=await db.Users.CountAsync(x=>x.Role!.RoleName=="Student",ct),totalTeachers=await db.Users.CountAsync(x=>x.Role!.RoleName=="Teacher",ct),totalConversations=await db.Conversations.CountAsync(ct),totalInteractions=await db.InteractionLogs.CountAsync(ct)});return Ok(new{role,totalConversations=await db.Conversations.CountAsync(x=>x.UserId==uid,ct),totalMessages=await db.ConversationMessages.CountAsync(x=>x.Conversation!.UserId==uid,ct),recentConversations=await db.Conversations.Where(x=>x.UserId==uid).OrderByDescending(x=>x.StartedAt).Take(5).Select(x=>new{x.ConversationId,x.Title,x.StartedAt,x.Status}).ToListAsync(ct)});}
}